// The Actor returns rows only on the first check or when the cheapest fare dropped.
const rows = $input.all().map((i) => i.json).filter((f) => typeof f.price === 'number').sort((a, b) => a.price - b.price);
if (!rows.length) return [];
const c = rows[0];
const was = c.previousCheapestPrice != null ? ` (was ${c.previousCheapestPrice})` : ' (first check)';
const lines = rows.slice(0, 5).map((f) => `• ${f.currency} ${f.price}: ${f.airlines?.join?.(', ') || f.airlines || ''}, ${f.stops === 0 ? 'nonstop' : `${f.stops} stop${f.stops > 1 ? 's' : ''}`}, ${f.duration || ''}`);
return [{ json: { message: `✈️ ${c.route}: cheapest ${c.currency} ${c.price}${was}\n${lines.join('\n')}\n<${c.googleFlightsUrl}|Open in Google Flights>` } }];
